1	// SPDX-License-Identifier: Apache-2.0
2	#![cfg_attr(not(test), allow(dead_code))]
3	//! Responses item assembly under the canonical rules (spec § 5, § 6.2, § 6.4, § 15).
4	//!
5	//! The decided value of a client-run item is always its `output_item.done` item (§ 5). The rules
6	//! make every other view a client SDK reads agree with it: the `added` item (the subset rule, A2),
7	//! the deltas and `*.done` events (R11–R14), and the item at the same index in the terminal
8	//! `output` (R9, R10). A stream that breaks a rule is a [`Deviation`], named after § 6.4.
9	//!
10	//! R5 lets one item be open at a time, so [`Assembly`] is one item-at-a-time state machine. Per
11	//! response it keeps the item ids and call ids (R8), the identity fields of every item (R9), and a
12	//! hash of every client-run `done` item (R10).
13	//!
14	//! Deltas are never retained. Each delta stream keeps a running SHA-256 hash, which is compared
15	//! with the hash of the `*.done` text and of the `done` item's text. So only the open item's
16	//! `added` item and the completed calls hold bytes ([`Assembly::retained`]). When the calls hold
17	//! more than the cap, they are dropped and the hold is never decided (749 D13, as an observed
18	//! hold): see [`Assembly::overflowed`]. Every rule is still checked after that point.
19	//!
20	//! The order of the checks on one event is: R1, R7, then the rules of the event's scope. After a
21	//! deviation, every later call to [`Assembly::accept`] returns the same deviation.
22	
23	use std::collections::HashSet;
24	
25	use serde_json::{Map, Value};
26	use sha2::{Digest, Sha256};
27	
28	use crate::json::{Malformed, check_numbers, opt_str, parse_value_strict};
29	use crate::protocol::{Deviation, MAX_IDENTIFIER_BYTES, raw_len};
30	use crate::report::{ReportDecision, ReportEntry};
31	use crate::responses::classify::{ItemClass, Scope, content_part_item, item_class, scope_of};
32	use crate::types::{ToolCall, ToolCallKind};
33	
34	/// The fields that R9 compares in `added`, `done` and the terminal `output`.
35	const IDENTITY: [&str; 5] = ["type", "id", "call_id", "namespace", "name"];
36	
37	/// The client-run item types whose openai-python 3.48.0 model has a `status` field
38	/// (`openai/types/responses/`). For these an absent `status` at `done` is a truncation (R15,
39	/// ruling T4b). `custom_tool_call`, `mcp_approval_request`, `custom_tool_call_output`,
40	/// `mcp_approval_response` and any type the SDK does not know have no such field.
41	const STATUS_TYPES: [&str; 7] = [
42	    "function_call",
43	    "computer_call",
44	    "local_shell_call",
45	    "shell_call",
46	    "apply_patch_call",
47	    "tool_search_call",
48	    "function_call_output",
49	];
50	
51	/// The prefix of the gateway's own rewrite ids (§ 6.5). No upstream item id may start with it.
52	const RESERVED_ID_PREFIX: &str = "msg_paigasus_";
53	
54	type Hash = [u8; 32];
55	
56	fn finish(h: &Sha256) -> Hash {
57	    let mut out = [0; 32];
58	    out.copy_from_slice(&h.clone().finalize());
59	    out
60	}
61	
62	fn hash_str(s: &str) -> Hash {
63	    let mut h = Sha256::new();
64	    h.update(s.as_bytes());
65	    finish(&h)
66	}
67	
68	fn feed_str(h: &mut Sha256, s: &str) {
69	    h.update((s.len() as u64).to_be_bytes());
70	    h.update(s.as_bytes());
71	}
72	
73	/// Feed a JSON value so that two values hash equal exactly when they are equal as JSON values
74	/// (`Value::eq`): object keys in sorted order, so key order is no difference.
75	fn feed_value(h: &mut Sha256, v: &Value) {
76	    match v {
77	        Value::Null => h.update([0]),
78	        Value::Bool(b) => h.update([1, u8::from(*b)]),
79	        Value::Number(n) => {
80	            h.update([2]);
81	            // `-0.0 == 0.0` as a `Value`, but the two print differently.
82	            let text = if n.is_f64() && n.as_f64() == Some(0.0) { "0.0".to_owned() } else { n.to_string() };
83	            feed_str(h, &text);
84	        }
85	        Value::String(s) => {
86	            h.update([3]);
87	            feed_str(h, s);
88	        }
89	        Value::Array(a) => {
90	            h.update([4]);
91	            h.update((a.len() as u64).to_be_bytes());
92	            a.iter().for_each(|x| feed_value(h, x));
93	        }
94	        Value::Object(o) => {
95	            h.update([5]);
96	            h.update((o.len() as u64).to_be_bytes());
97	            let mut keys: Vec<&String> = o.keys().collect();
98	            keys.sort();
99	            for k in keys {
100	                feed_str(h, k);
101	                feed_value(h, &o[k.as_str()]);
102	            }
103	        }
104	    }
105	}
106	
107	fn hash_value(v: &Value) -> Hash {
108	    let mut h = Sha256::new();
109	    feed_value(&mut h, v);
110	    finish(&h)
111	}
112	
113	/// The fixed name of a built-in client-run kind (§ 5).
114	fn fixed_name(kind: ToolCallKind) -> Option<&'static str> {
115	    match kind {
116	        ToolCallKind::Computer => Some("computer"),
117	        ToolCallKind::LocalShell => Some("local_shell"),
118	        ToolCallKind::Shell => Some("shell"),
119	        ToolCallKind::ApplyPatch => Some("apply_patch"),
120	        ToolCallKind::ToolSearch => Some("tool_search"),
121	        _ => None,
122	    }
123	}
124	
125	fn text_of(item: &Map<String, Value>, key: &'static str) -> Result<String, Malformed> {
126	    match item.get(key) {
127	        Some(Value::String(s)) => Ok(s.clone()),
128	        _ => Err(Malformed(key)),
129	    }
130	}
131	
132	/// `(namespace, name)` of a client-run item (§ 5).
133	fn name_of(item: &Map<String, Value>, kind: ToolCallKind) -> Result<(Option<String>, String), Malformed> {
134	    if let Some(name) = fixed_name(kind) {
135	        return Ok((None, name.to_owned()));
136	    }
137	    Ok(match kind {
138	        ToolCallKind::Function => (opt_str(item.get("namespace"), "namespace")?, text_of(item, "name")?),
139	        ToolCallKind::Custom => (opt_str(item.get("namespace"), "namespace")?, text_of(item, "name")?),
140	        ToolCallKind::McpApprovalRequest => (opt_str(item.get("server_label"), "server_label")?, text_of(item, "name")?),
141	        ToolCallKind::Other => (None, text_of(item, "type")?),
142	        _ => return Err(Malformed("kind")),
143	    })
144	}
145	
146	/// The call of one client-run Responses item, by the § 5 table. Shared by the stream (the `done`
147	/// item) and the body path (an `output[]` item).
148	///
149	/// `namespace` is the `namespace` of a function or custom call (when present) and the
150	/// `server_label` of an `mcp_approval_request` (§ 5, ruling T4a).
151	/// `id` is the `call_id`, or the item `id` for `mcp_approval_request`. A server `tool_search_call`
152	/// may have no `call_id`. Kind `Other` takes the `call_id` when the item has one, else the item
153	/// `id` (§ 5 gives no row for it). `arguments` is `arguments` for a function (`""` becomes `"{}"`),
154	/// `input` for a custom call, and for every other kind the item as compact JSON in its own key
155	/// order, with `status` removed. The item's numbers must be exact (`check_numbers`, § 7.1).
156	pub(crate) fn tool_call(position: u32, item: &Map<String, Value>, kind: ToolCallKind) -> Result<ToolCall, Malformed> {
157	    item.values().try_for_each(check_numbers)?;
158	    let (namespace, name) = name_of(item, kind)?;
159	    let id = match kind {
160	        ToolCallKind::McpApprovalRequest => Some(text_of(item, "id")?),
161	        ToolCallKind::ToolSearch => opt_str(item.get("call_id"), "call_id")?,
162	        ToolCallKind::Other => match opt_str(item.get("call_id"), "call_id")? {
163	            Some(c) => Some(c),
164	            None => opt_str(item.get("id"), "id")?,
165	        },
166	        _ => Some(text_of(item, "call_id")?),
167	    };
168	    let arguments = match kind {
169	        ToolCallKind::Function => {
170	            let a = text_of(item, "arguments")?;
171	            if a.is_empty() { "{}".to_owned() } else { a }
172	        }
173	        ToolCallKind::Custom => text_of(item, "input")?,
174	        _ => {
175	            let stripped: Map<String, Value> = item.iter().filter(|(k, _)| *k != "status").map(|(k, v)| (k.clone(), v.clone())).collect();
176	            serde_json::to_string(&Value::Object(stripped)).expect("a Value always serializes")
177	        }
178	    };
179	    Ok(ToolCall {
180	        choice: 0,
181	        position,
182	        id,
183	        name,
184	        namespace,
185	        kind,
186	        arguments,
187	    })
188	}
189	
190	/// What a frame is to the item it belongs to.
191	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
192	pub(crate) enum ItemFrame {
193	    /// No item: a lifecycle, terminal, response-level, keepalive or error record.
194	    Other,
195	    Added,
196	    /// An item-scoped event between `added` and `done`.
197	    Middle,
198	    Done,
199	}
200	
201	/// What one accepted record means to the stream.
202	#[derive(Debug, Clone, PartialEq)]
203	pub(crate) struct Effect {
204	    /// The response hold opened at this record: the first client-run `added` (D10).
205	    pub(crate) opened: bool,
206	    /// The `output_index` of the client-run item this frame belongs to. `None` for every other
207	    /// frame, the frames of tool-free and provider-run items included.
208	    pub(crate) item: Option<u32>,
209	    pub(crate) frame: ItemFrame,
210	    /// The `unenforceable` entry of a provider-run item, at its `added` (§ 6.2).
211	    pub(crate) report: Option<ReportEntry>,
212	    /// The record is the terminal event (R3).
213	    pub(crate) terminal: bool,
214	}
215	
216	impl Effect {
217	    fn other() -> Self {
218	        Effect {
219	            opened: false,
220	            item: None,
221	            frame: ItemFrame::Other,
222	            report: None,
223	            terminal: false,
224	        }
225	    }
226	}
227	
228	/// A delta stream: the running hash of the deltas and the hash of its `*.done` text.
229	#[derive(Default)]
230	struct Text {
231	    deltas: Sha256,
232	    done: Option<Hash>,
233	    /// Any delta or `*.done` event arrived.
234	    touched: bool,
235	    /// A delta after the `*.done` event, a second `*.done` event, or a value that is no string.
236	    broken: bool,
237	}
238	
239	impl Text {
240	    fn delta(&mut self, d: Option<&Value>) -> bool {
241	        self.touched = true;
242	        match d {
243	            Some(Value::String(s)) if self.done.is_none() => self.deltas.update(s.as_bytes()),
244	            _ => self.broken = true,
245	        }
246	        !self.broken
247	    }
248	
249	    /// Record the `*.done` text. `false` when the stream is broken or the text is not the deltas.
250	    fn done(&mut self, t: Option<&Value>) -> bool {
251	        self.touched = true;
252	        match t {
253	            Some(Value::String(s)) if self.done.is_none() => self.done = Some(hash_str(s)),
254	            _ => self.broken = true,
255	        }
256	        !self.broken && self.done == Some(finish(&self.deltas))
257	    }
258	
259	    /// The deltas, and the `*.done` text when one arrived, both equal `value`.
260	    fn agrees(&self, value: &str) -> bool {
261	        let h = hash_str(value);
262	        !self.broken && finish(&self.deltas) == h && self.done.is_none_or(|d| d == h)
263	    }
264	}
265	
266	/// One `shell_call` command (R13): the hash of its `added` command plus its deltas.
267	struct Command {
268	    text: Sha256,
269	    done: Option<Hash>,
270	}
271	
272	/// The one open item (R5).
273	struct Open {
274	    index: u32,
275	    ty: String,
276	    id: String,
277	    class: ItemClass,
278	    /// The `added` item of a client-run item, for the subset rule. Counted in `held`.
279	    added: Option<Value>,
280	    text: Text,
281	    commands: Vec<Command>,
282	}
283	
284	/// What the stream keeps of every item.
285	struct Seen {
286	    identity: [Option<Value>; 5],
287	    done: bool,
288	    /// The hash of a client-run item's `done` item, for R10.
289	    done_hash: Option<Hash>,
290	}
291	
292	fn identity(item: &Map<String, Value>) -> [Option<Value>; 5] {
293	    IDENTITY.map(|k| item.get(k).cloned())
294	}
295	
296	/// R8: an object with a string `type` and a non-empty string `id`. The identity fields and
297	/// `server_label` are strings or `null` where present, and none is longer than
298	/// `MAX_IDENTIFIER_BYTES`.
299	fn item_shape(v: Option<&Value>) -> Result<(&Map<String, Value>, &str, &str), Deviation> {
300	    let bad = Deviation("item_shape");
301	    let Some(Value::Object(m)) = v else { return Err(bad) };
302	    let Some(Value::String(ty)) = m.get("type") else { return Err(bad) };
303	    let Some(Value::String(id)) = m.get("id") else { return Err(bad) };
304	    if id.is_empty() {
305	        return Err(bad);
306	    }
307	    let named = IDENTITY.iter().chain(&["server_label"]).filter_map(|k| m.get(*k));
308	    let mut long = false;
309	    for v in named {
310	        match v {
311	            Value::Null => {}
312	            Value::String(s) => long |= s.len() > MAX_IDENTIFIER_BYTES,
313	            _ => return Err(bad),
314	        }
315	    }
316	    if long {
317	        return Err(Deviation("long_identifier"));
318	    }
319	    Ok((m, ty, id))
320	}
321	
322	/// The subset rule (§ 6.4, A2): every field of `added`, at any depth, except the top-level
323	/// `status`, is `null`, `""`, `[]` or equal to the same field of `done`, and `done` has every
324	/// field that `added` has. An object field follows the rule inside; an array is `[]` or equal.
325	fn subset(added: &Map<String, Value>, done: &Map<String, Value>, top: bool) -> bool {
326	    added.iter().all(|(k, a)| {
327	        if top && k == "status" {
328	            return true;
329	        }
330	        let Some(d) = done.get(k) else { return false };
331	        match a {
332	            Value::Null => true,
333	            Value::String(s) if s.is_empty() => true,
334	            Value::Array(x) if x.is_empty() => true,
335	            Value::Object(ao) => matches!(d, Value::Object(dobj) if subset(ao, dobj, false)),
336	            _ => a == d,
337	        }
338	    })
339	}
340	
341	fn index_of(v: Option<&Value>) -> Option<u32> {
342	    v.and_then(Value::as_u64).and_then(|i| u32::try_from(i).ok())
343	}
344	
345	/// `action.commands` of a `shell_call` item: `None` when absent or `null`.
346	fn shell_commands(item: &Map<String, Value>) -> Result<Option<&Vec<Value>>, Deviation> {
347	    let bad = Deviation("shell_command_mismatch");
348	    match item.get("action") {
349	        None | Some(Value::Null) => Ok(None),
350	        Some(Value::Object(a)) => match a.get("commands") {
351	            None | Some(Value::Null) => Ok(None),
352	            Some(Value::Array(c)) => Ok(Some(c)),
353	            Some(_) => Err(bad),
354	        },
355	        Some(_) => Err(bad),
356	    }
357	}
358	
359	/// R13 per command event. Indexes appear in order, and a command ends before the next starts.
360	fn shell_event(commands: &mut Vec<Command>, ty: &str, ev: &Map<String, Value>) -> Result<(), Deviation> {
361	    let bad = Deviation("shell_command_mismatch");
362	    let i = index_of(ev.get("command_index")).ok_or(bad)? as usize;
363	    let text = |k: &str| match ev.get(k) {
364	        Some(Value::String(s)) => Ok(s.as_str()),
365	        _ => Err(bad),
366	    };
367	    if ty == "response.shell_call_command.added" {
368	        if i != commands.len() || commands.last().is_some_and(|c| c.done.is_none()) {
369	            return Err(bad);
370	        }
371	        let mut h = Sha256::new();
372	        h.update(text("command")?.as_bytes());
373	        commands.push(Command { text: h, done: None });
374	        return Ok(());
375	    }
376	    if i + 1 != commands.len() {
377	        return Err(bad);
378	    }
379	    let c = commands.last_mut().filter(|c| c.done.is_none()).ok_or(bad)?;
380	    if ty == "response.shell_call_command.delta" {
381	        c.text.update(text("delta")?.as_bytes());
382	    } else {
383	        let h = hash_str(text("command")?);
384	        if finish(&c.text) != h {
385	            return Err(bad);
386	        }
387	        c.done = Some(h);
388	    }
389	    Ok(())
390	}
391	
392	/// The per-kind rules of a client-run `done` item (R11–R14).
393	fn check_client(kind: ToolCallKind, open: &Open, added: &Map<String, Value>, done: &Map<String, Value>, completed: bool) -> Result<(), Deviation> {
394	    match kind {
395	        ToolCallKind::Function | ToolCallKind::Custom => {
396	            // R15 takes precedence over R11 (A3), and R12 is the same rule with `input`.
397	            if !completed {
398	                return Ok(());
399	            }
400	            let function = kind == ToolCallKind::Function;
401	            let (key, mismatch, added_label) = if function {
402	                ("arguments", "arguments_mismatch", "added_arguments")
403	            } else {
404	                ("input", "input_mismatch", "input_mismatch")
405	            };
406	            if !matches!(added.get(key), Some(Value::String(s)) if s.is_empty()) {
407	                return Err(Deviation(added_label));
408	            }
409	            let Some(Value::String(text)) = done.get(key) else { return Err(Deviation(mismatch)) };
410	            if !open.text.agrees(text) {
411	                return Err(Deviation(mismatch));
412	            }
413	            if function && !text.is_empty() && parse_value_strict(text.as_bytes()).is_err() {
414	                return Err(Deviation("incomplete_arguments"));
415	            }
416	        }
417	        ToolCallKind::Shell => {
418	            let bad = Deviation("shell_command_mismatch");
419	            let done_commands = shell_commands(done)?.map_or(&[][..], Vec::as_slice);
420	            // Ruling F2: `added` commands are `[]` or the `done` commands.
421	            if let Some(a) = shell_commands(added)?
422	                && !a.is_empty()
423	                && a.as_slice() != done_commands
424	            {
425	                return Err(bad);
426	            }
427	            if open.commands.len() != done_commands.len() {
428	                return Err(bad);
429	            }
430	            for (c, d) in open.commands.iter().zip(done_commands) {
431	                let Value::String(d) = d else { return Err(bad) };
432	                if c.done != Some(hash_str(d)) {
433	                    return Err(bad);
434	                }
435	            }
436	        }
437	        ToolCallKind::ApplyPatch => {
438	            let diff = match done.get("operation") {
439	                Some(Value::Object(op)) => op.get("diff"),
440	                _ => None,
441	            };
442	            let ok = match diff {
443	                Some(Value::String(d)) => open.text.agrees(d),
444	                None | Some(Value::Null) => !open.text.touched,
445	                Some(_) => false,
446	            };
447	            if !ok {
448	                return Err(Deviation("diff_mismatch"));
449	            }
450	        }
451	        _ => {}
452	    }
453	    Ok(())
454	}
455	
456	/// The assembly of one Responses stream (spec § 6.4).
457	pub(crate) struct Assembly {
458	    cap: usize,
459	    failed: Option<Deviation>,
460	    started: bool,
461	    ended: bool,
462	    response_id: Option<String>,
463	    /// R7: whether events carry `sequence_number`, fixed by the first non-exempt event.
464	    numbered: Option<bool>,
465	    last_number: Option<u64>,
466	    items: Vec<Seen>,
467	    open: Option<Open>,
468	    ids: HashSet<String>,
469	    call_ids: HashSet<String>,
470	    /// The `output_index` of every client-run item, in order: a call's slot is its place here.
471	    client: Vec<u32>,
472	    /// `(output_index, display_name)` of every client-run item so far.
473	    names: Vec<(u32, String)>,
474	    calls: Vec<ToolCall>,
475	    hold_open: bool,
476	    truncated: bool,
477	    overflowed: bool,
478	    /// The bytes of the open `added` item and of the calls' arguments.
479	    held: usize,
480	}
481	
482	impl Assembly {
483	    /// `cap` is the stream's `max_held_bytes`: the calls of a response that hold more are dropped.
484	    pub(crate) fn with_cap(cap: usize) -> Self {
485	        Assembly {
486	            cap,
487	            failed: None,
488	            started: false,
489	            ended: false,
490	            response_id: None,
491	            numbered: None,
492	            last_number: None,
493	            items: Vec::new(),
494	            open: None,
495	            ids: HashSet::new(),
496	            call_ids: HashSet::new(),
497	            client: Vec::new(),
498	            names: Vec::new(),
499	            calls: Vec::new(),
500	            hold_open: false,

