        // `response.shell_call_command.*` is the one item-scoped family with no `item_id`.
        let no_item_id = ty.starts_with("response.shell_call_command.");
        match ev.get("item_id") {
            Some(Value::String(s)) if *s == open.id => {}
            None if no_item_id => {}
