1722	    fn assemble_file(path: &std::path::Path) -> Result<Assembly, String> {
1723	        let mut splitter = crate::sse::SseSplitter::new(16 * 1024 * 1024);
1724	        let bytes = std::fs::read(path).unwrap();
1725	        let mut items = splitter.push(&bytes);
1726	        items.extend(splitter.finish());
1727	        let mut a = Assembly::with_cap(crate::limits::Limits::defaults().max_held_bytes);
1728	        let mut terminal = false;
1729	        for item in items {
1730	            let crate::sse::SseItem::Record(r) = item else { return Err("oversized".to_owned()) };
1731	            match classify(&r).map_err(|e| e.to_string())? {
1732	                Event::Known { ty, value } => terminal |= a.accept(ty, &value).map_err(|d| d.0.to_owned())?.terminal,
1733	                Event::Done => {}
1734	                Event::UpstreamError(_) => return Err("upstream error".to_owned()),
1735	            }
1736	        }
1737	        if terminal { Ok(a) } else { Err("no terminal".to_owned()) }
1738	    }
